        }
        Cmd::Get { file, path } => {
            maybe_verify_integrity(&file, integrity)?;
            let doc = read_toml(&file)?;
            let out = match path.as_deref() {
                None | Some("") => toml_to_json(&doc),
                Some(p) => toml_to_json(
