            maybe_verify_integrity(&file, integrity)?;
            read_toml(&file)?;
            println!("{{\"ok\":true}}");
        }
        Cmd::Items { op } => items_dispatch(op, allow_outside, integrity)?,
        Cmd::Blocks { op } => blocks_dispatch(op)?,
